import React, { useState, useEffect, useRef } from 'react'
import "./Header.scss"
import { CircleUserRound, LogOut, Settings, BookUser } from 'lucide-react'
import SignedInDrop from './SignedInDrop'

const Header = () => {
  const [username, setUsername] = useState('')

  const toggleDropdown = () => {
    setIsDropdownOpen(!isDropdownOpen) // profile click reveals or hides dropdown
    setUsername("Brian")

  }

  const handleClickOutside = (e) => {
    if (dropdownRef.current && !dropdownRef.current.contains(e.target)) {
      setIsDropdownOpen(false)
    }
  }

  useEffect(() => {
    if (isDropdownOpen) {
      document.addEventListener('mousedown', handleClickOutside)
    } else {
      document.removeEventListener('mousedown', handleClickOutside)
    }

    return () => {
      document.removeEventListener('mousedown', handleClickOutside)
    }
  }, [isDropdownOpen])

  return (
    <div className="header-container">
      <div className="header-section-container">
        <div className="profile-container">
          <CircleUserRound className="profile-icon" onClick={toggleDropdown}/>
          {isDropdownOpen && (
            <SignedInDrop />
          )}
        </div>
      </div>
    </div>
  )
}

export default Header
